   "code": "// Event-sourced account: state = fold over events; commands validate and append\nconst apply = (s, e) => {\n  switch (e.type) {\n    case 'Opened': return { owner: e.owner, balance: 0, version: s.version + 1 };\n    case 'Deposited': return { ...s, balance: s.balance + e.amount, version: s.version + 1 };\n    case 'Withdrawn': return { ...s, balance: s.balance - e.amount, version: s.version + 1 };\n  }\n};\nconst load = events => events.reduce(apply, { balance: 0, version: 0 });\n\nfunction withdraw(events, amount) {\n  const s = load(events);\n  if (amount > s.balance) throw new Error('insufficient funds');\n  return { expectedVersion: s.version, event: { type: 'Withdrawn', amount } };  // append only if version still matches\n}\n\nconst history = [{ type: 'Opened', owner: 'Ana' }, { type: 'Deposited', amount: 100 }, { type: 'Withdrawn', amount: 30 }, { type: 'Deposited', amount: 5 }];\nconsole.log(load(history));                    // { owner: 'Ana', balance: 75, version: 4 }\nconsole.log(withdraw(history, 50));            // { expectedVersion: 4, event: { type: 'Withdrawn', amount: 50 } }\ntry { withdraw(history, 80); } catch (e) { console.log(e.message); } // insufficient funds\n\n// A projection: a different read model from the same events\nconst statement = history.filter(e => e.amount).map(e => (e.type === 'Withdrawn' ? '-' : '+') + e.amount);\nconsole.log(statement.join(' '));               // +100 -30 +5",
