   "code": "// Tumbling windows by EVENT time with a watermark and allowed lateness\nfunction windowCounts(events, windowMs, watermarkDelayMs) {\n  const windows = new Map(); let maxSeen = 0; const emitted = []; const late = [];\n  for (const e of events) {                       // events arrive in processing order\n    maxSeen = Math.max(maxSeen, e.t);\n    const watermark = maxSeen - watermarkDelayMs;\n    const start = Math.floor(e.t / windowMs) * windowMs;\n    if (start + windowMs <= watermark && !windows.has(start)) { late.push(e); continue; }\n    windows.set(start, (windows.get(start) || 0) + 1);\n    for (const [s, n] of windows) if (s + windowMs <= watermark) { emitted.push([s, n]); windows.delete(s); }\n  }\n  return { emitted, open: [...windows], late };\n}\n// event times in seconds (x1000 ms); one event from t=5 s arrives late, after t=70 s\nconst ev = [1, 12, 30, 61, 65, 70, 5, 125, 130].map(s => ({ t: s * 1000 }));\nconsole.log(JSON.stringify(windowCounts(ev, 60000, 10000)));",
